'use client'

import { useState, useEffect } from 'react'
import { useSearchParams } from 'next/navigation'
import { useLang } from '@/lib/LanguageContext'
import StoryTab from './tabs/StoryTab'
import ProduceTab from './tabs/ProduceTab'
import QualityTab from './tabs/QualityTab'
import ReviewsTab from './tabs/ReviewsTab'
import FarmMediaTab from './tabs/FarmMediaTab'
import { CartFab } from '@/components/consumer/Cart'

type Props = {
  farmer: Record<string, unknown>
  produce: Record<string, unknown>[]
  reviews: Record<string, unknown>[]
  media: Record<string, unknown>[]
}

export default function TabSection({ farmer, produce, reviews, media }: Props) {
  const { tx } = useLang()
  const [activeTab, setActiveTab] = useState(1)
  const searchParams = useSearchParams()
  const isEditMode = searchParams.get('edit') === 'true'

  const TABS = [tx.story, tx.produce, tx.quality, tx.reviews, tx.farm]

  return (
    <div>
      <div className="sticky top-[53px] z-40 bg-white border-b border-gray-200">
        <div className="flex overflow-x-auto scrollbar-hide">
          {TABS.map((tab, i) => (
            <button
              key={tab}
              onClick={() => setActiveTab(i)}
              className={`flex-shrink-0 px-4 py-3 text-sm font-semibold border-b-2 transition-colors ${
                activeTab === i
                  ? 'border-green-700 text-green-700'
                  : 'border-transparent text-gray-500'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      <div className="px-4 py-4">
        {activeTab === 0 && <StoryTab farmer={farmer} />}
        {activeTab === 1 && <ProduceTab farmer={farmer} produce={produce} isEditMode={isEditMode} />}
        {activeTab === 2 && <QualityTab farmer={farmer} produce={produce} />}
        {activeTab === 3 && <ReviewsTab reviews={reviews} farmerId={farmer.id as string} />}
        {activeTab === 4 && <FarmMediaTab media={media} />}
      </div>
      <CartFab />
    </div>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest, clearSessionCookie } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) {
    return NextResponse.json({ consumer: null }, { status: 200 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: user } = await supabase
    .from('consumers_auth')
    .select('id, name, phone, suspended, suspended_reason')
    .eq('id', session.consumerId)
    .maybeSingle()

  if (!user) {
    // Cookie references a deleted account — clear it so the client logs out.
    const res = NextResponse.json({ consumer: null }, { status: 200 })
    clearSessionCookie(res)
    return res
  }

  if (user.suspended === true) {
    // Suspended account: clear the cookie so they can't perform authenticated
    // actions, but return the moderator's reason so the client can show a
    // highlighted banner in the header explaining why.
    const reason = (user.suspended_reason as string | null)?.trim() || null
    const res = NextResponse.json({ consumer: null, suspended: true, suspendedReason: reason }, { status: 200 })
    clearSessionCookie(res)
    return res
  }

  return NextResponse.json({ consumer: { id: user.id, name: user.name, phone: user.phone } })
}

